INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-transport-arrival-conversation',@lesson,1,'conversation_speaking','خودت گفت‌وگو را شروع کن: زمان رسیدن قطار را بپرس.','پرسش زمان رسیدن و پاسخ ساعت یک نیاز مستقل در سفر هستند.',(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-transport-arrival' LIMIT 1),CAST('{"interaction":"read_aloud_exchange","openingInitiator":"learner"}' AS JSON),CAST('["other","persian_translation_added","character_metadata_added"]' AS JSON),NULL,'not_required');
