INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-transport-arrival-choice',@lesson,2,'multiple_choice','کدام پرسش دربارهٔ زمان رسیدن است؟','زبان‌آموز باید رسیدن را از حرکت و سکو تشخیص دهد.',NULL,CAST('{"options":[{"textTarget":"Wann kommt dieser Zug in Berlin an?","translationFa":"این قطار چه زمانی به برلین می‌رسد؟","correct":true},{"textTarget":"Wann fährt der Zug ab?","translationFa":"قطار چه زمانی حرکت می‌کند؟","correct":false},{"textTarget":"Von welchem Bahnsteig fährt der Zug ab?","translationFa":"قطار از کدام سکو حرکت می‌کند؟","correct":false}]}' AS JSON),CAST('["options_selected_from_source_material","persian_translation_added"]' AS JSON),NULL,'not_required');
SET @act := (SELECT id FROM activities WHERE activity_key='act-de-a1-transport-arrival-choice' LIMIT 1);
