SELECT @act,curriculum_target_id FROM unit_targets WHERE unit_id=@unit;
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-transport-arrival-order',@lesson,3,'word_order','پرسش زمان رسیدن را دوباره بساز.','پرسش کلیدی درس در پایان به بازیابی فعال منتقل می‌شود.',NULL,CAST('{"sourceText":"Wann kommt dieser Zug in Berlin an?","sourceTextFa":"این قطار چه زمانی به برلین می‌رسد؟","tokens":["Wann","kommt","dieser","Zug","in","Berlin","an?"],"answer":["Wann","kommt","dieser","Zug","in","Berlin","an?"]}' AS JSON),CAST('["sentence_tokenized_for_word_order","persian_translation_added"]' AS JSON),NULL,'not_required');
