('act-de-a1-weather-rain-conversation',@lesson,1,'conversation_speaking','خودت گفت‌وگو را شروع کن: دربارهٔ باران بپرس و توصیهٔ مربوط به چتر را بفهم.','مکالمهٔ منبع‌دار هوا را مستقیماً به تصمیم روزانه وصل می‌کند.',(SELECT id FROM dialogues WHERE dialogue_key='dlg-de-a1-weather-rain-plan' LIMIT 1),CAST('{"interaction":"read_aloud_exchange","openingInitiator":"learner"}' AS JSON),CAST('["verbatim_dialogue","persian_translation_added","character_metadata_added"]' AS JSON),NULL,'not_required');
