UPDATE language_levels SET
 structure_rationale='A1 نیازمحور باقی می‌ماند، اما از این سطح به بعد هر واحد نهایی باید بین ۳ تا ۱۲ درس داشته باشد. تعداد دقیق داخل این بازه بر اساس گسترهٔ موضوع، پیش‌نیازها، تنوع مهارتی، بازیابی و کاربرد واقعی تعیین می‌شود؛ نه بر اساس پرکردن سهمیه.',
 coverage=CAST('{"communicativeTargets":["فهم و استفاده از عبارت‌ها و جمله‌های ساده و پرتکرار در موقعیت‌های آشنای روزمره","معرفی خود و دیگران و پرسیدن و پاسخ‌دادن دربارهٔ اطلاعات شخصی پایه","پرسیدن و گفتن اطلاعات ساده دربارهٔ خانواده، افراد آشنا و روابط نزدیک","صحبت ساده دربارهٔ محل زندگی، خانه و محیط نزدیک","پرسیدن و پاسخ‌دادن دربارهٔ کار، مدرسه و کارهای روزمرهٔ پایه","خرید ساده: پرسیدن قیمت، مقدار، نیاز و انتخاب کالا","سفارش و درخواست سادهٔ غذا و نوشیدنی و فهم پاسخ‌های رایج","پرسیدن و فهم زمان، تاریخ، ساعت، برنامه و قرار ساده","پرسیدن و دادن مسیر و اطلاعات مکانی بسیار ساده","درخواست، اجازه، کمک و پاسخ مؤدبانه در موقعیت‌های روزمره","فهم گفت‌وگوهای کوتاه روزمره وقتی آهسته و روشن گفته می‌شوند","فهم اطلاعات اصلی در پیام تلفنی کوتاه و اعلام عمومی ساده","خواندن و فهم متن‌های بسیار کوتاه مانند یادداشت، آگهی، تابلو و اعلان","تکمیل فرم ساده و نوشتن یک پیام شخصی کوتاه دربارهٔ موقعیت روزمره","پرسیدن و پاسخ‌دادن به سؤال‌های روزمره و انجام یک درخواست ساده در گفت‌وگوی کوتاه","بیان و فهم علائم بسیار سادهٔ بیماری و نیازهای پایهٔ دارویی","گرفتن بلیت و فهم اطلاعات بسیار سادهٔ حمل‌ونقل عمومی","پرسیدن و فهم هوای فعلی، پیش‌بینی ساده و دمای روزمره"],"linguisticTargets":["گسترش واژگان پایه برای شخص، خانواده، خانه، خرید، کار یا مدرسه، غذا، زمان و محیط نزدیک","ساخت جملهٔ سادهٔ خبری و پرسشی با ترتیب واژهٔ پایه در آلمانی","پرسش‌های W و پرسش‌های بله/خیر در موقعیت‌های روزمره","ضمیرهای شخصی و تمایز کاربردی خطاب دوستانه و رسمی","فعل‌های پرتکرار در زمان حال و الگوهای صرفی لازم برای ارتباط A1","منفی‌سازی پایه با الگوهای منبع‌دار مانند nicht و kein پس از ثبت منبع مناسب","اسم، جنس، حرف تعریف و جمع در حد لازم برای واژگان پرتکرار A1","حالت‌های دستوری پایه در حد کاربردهای روزمره و منبع‌دار، بدون آموزش انتزاعیِ زودهنگام","عدد، مقدار، قیمت، تاریخ و ساعت در دامنهٔ روزمرهٔ A1","حروف اضافهٔ بسیار پرتکرار زمان و مکان در عبارت‌های منبع‌دار","افعال وجهی و الگوهای درخواست ساده فقط پس از تثبیت منابع آلمانی قابل‌بازاستفاده","تلفظ قابل‌فهمِ واژه‌ها و جمله‌های کوتاه، با تمرکز بر تفاوت‌های پرتکرار آلمانی که در منابع این سطح ظاهر می‌شوند"],"situations":["معرفی و آشنایی","خانواده و افراد نزدیک","خانه و محل زندگی","کار، مدرسه و روتین روزانه","خرید و پرداخت","کافه، رستوران و سفارش","زمان، تاریخ، برنامه و قرار","خیابان، مسیر و مکان‌های عمومی","درخواست کمک، اجازه و خدمات روزمره","فرم، یادداشت، پیام کوتاه و تماس یا اعلام ساده","پزشک، علائم ساده و داروخانه","بلیت، قطار، اتوبوس و اطلاعات حرکت","آب‌وهوا، باران و دما"],"gaps":[]}' AS JSON),
 completion_assessment=CAST('{"reviewedAt":"2026-09-18T08:20:00Z","cefrCoverageComplete":true,"progressionComplete":true,"practiceAndRetrievalComplete":true,"skillModeCoverageComplete":true,"requiredGaps":[],"qualityReview":{"overallScore":9.2,"dimensionScores":{"cefrCoverage":9.4,"pedagogicalProgression":9.2,"practiceAndRetrieval":9.1,"activityQualityAndVariety":9,"linguisticAccuracyAndNaturalness":9.3,"sourceQualityAndCurrency":9.4,"learnerSupportAndClarity":9.1,"qaIntegrity":9.3},"rationale":"پوشش الزامی A1 حفظ شده و دامنهٔ کاربرد روزمره با سه واحد منبع‌دار تازه گسترش یافته است: سلامت و داروخانه، بلیت و حمل‌ونقل عمومی، و آب‌وهوا و دما. این سه واحد فقط برای افزایش تعداد اضافه نشده‌اند؛ هرکدام سه کار ارتباطی مستقل دارند و مسیر آموزشی از فهم موقعیت به تمرین و بازیابی هدایت‌شده می‌رسد.","strengths":["همهٔ هدف‌های الزامی A1 همچنان نگاشت واقعی به واحد، درس یا فعالیت دارند.","۱۴ درس جایگزین‌شدهٔ قبلی هدف ارتباطی مستقل دارند و به گفت‌وگوی درس قبلی متکی نیستند.","سه واحد تازه شکاف‌های روزمرهٔ سلامت، حمل‌ونقل عمومی و آب‌وهوا را با منابع قابل‌بازاستفاده پوشش می‌دهند.","هر ۱۳ واحد نهایی دقیقاً بر اساس نیاز آموزشی در بازهٔ ۳ تا ۱۲ درس قرار دارد.","ترتیب فعالیت‌ها از مکالمهٔ کاربردی به تشخیص و سپس بازیابی هدایت‌شده حرکت می‌کند.","متن آلمانی زبان‌آموز از بخش‌های مشخص منابع قابل‌بازاستفاده می‌آید یا تبدیل مکانیکی و قابل‌ردیابیِ نمونهٔ منبع است."],"remainingWeaknesses":["گفت‌وگوهای تازهٔ این بازطراحی و سه واحد جدید هنوز فایل صوتی تازه ندارند و باید پیش از آماده‌اعلام‌شدن صوتی سطح تولید و بررسی شوند.","تولید نوشتاری در ساختار فعلی برنامه هدایت‌شده است و ورودی آزاد تایپی ندارد."]},"scopeExclusions":["ورودی آزاد تایپی در ساختار فعلی فعالیت‌ها پشتیبانی نمی‌شود؛ تولید نوشتاری A1 در این نسخه به تکمیل و بازسازی هدایت‌شده محدود است."]}' AS JSON),
 notes='A1 اکنون ۱۳ واحد و ۳۹ درس دارد. سه واحد تازهٔ سلامت و داروخانه، بلیت و حمل‌ونقل عمومی، و آب‌وهوا و دما به‌عنوان شکاف‌های کاربردی روزمره اضافه شده‌اند. هر سه واحد سه درس مستقل دارند و قانون ۳ تا ۱۲ درس برای همهٔ واحدهای نهایی رعایت می‌شود. فایل‌های صوتی موجود حفظ می‌شوند و وضعیت صوتی سطح تا تولید گفت‌وگوهای تازه نیازمند به‌روزرسانی است.',
 status='final',
 audio_status='stale'
WHERE id=@level;
COMMIT;
